import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import './LoginPage.css';

export default function LoginPage() {
  const { login } = useAuth();
  const nav = useNavigate();
  const [form, setForm]   = useState({ username: '', password: '' });
  const [error, setError] = useState('');
  const [busy, setBusy]   = useState(false);
  const [show, setShow]   = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setError(''); setBusy(true);
    try {
      const u = await login(form.username, form.password);
      nav(u.role === 'admin' ? '/admin' : '/dept');
    } catch (err) {
      setError(err.response?.data?.error || 'Login failed. Please try again.');
    } finally { setBusy(false); }
  };

  return (
    <div className="login-bg">
      <div className="login-card">
        <div className="login-seal">
          <div className="seal-circle"><span>PTS</span></div>
        </div>
        <h1 className="login-title">PAPER TRACKING SYSTEM</h1>
        <p className="login-sub">Municipality of Calape, Bohol</p>
        <div className="login-divider" />

        <form onSubmit={submit}>
          {error && <div className="alert a-err">{error}</div>}

          <div className="fg">
            <label className="lbl">Username</label>
            <input className="inp" type="text" autoComplete="username" required
              value={form.username} placeholder="Enter username"
              onChange={e => setForm(f => ({ ...f, username: e.target.value }))} />
          </div>

          <div className="fg">
            <label className="lbl">Password</label>
            <div style={{ position:'relative' }}>
              <input className="inp" type={show ? 'text' : 'password'} autoComplete="current-password" required
                value={form.password} placeholder="Enter password" style={{ paddingRight:40 }}
                onChange={e => setForm(f => ({ ...f, password: e.target.value }))} />
              <button type="button" onClick={() => setShow(v => !v)}
                style={{ position:'absolute', right:10, top:'50%', transform:'translateY(-50%)', background:'none', border:'none', cursor:'pointer', fontSize:16, opacity:.6 }}>
                {show ? '🙈' : '👁️'}
              </button>
            </div>
          </div>

          <button type="submit" className="btn btn-gold btn-lg btn-full" disabled={busy}>
            {busy ? 'Signing in…' : 'Sign In'}
          </button>
          <p className="login-hint">Admin and Department accounts sign in here.</p>
        </form>
      </div>
    </div>
  );
}
